from typing import List, TypeVar, Union

X = TypeVar("X", bound=str)

def string_xor(a: X, b: X) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    """
    result = ""
    for i in range(len(a) if len(a) > len(b) else len(b)):
        if i < len(a) and i < len(b):
            bit_xor = str(int(a[i]) ^ int(b[i]))
        elif i < len(a):
            bit_xor = "0" if int(a[i]) else "1"
        else:
            bit_xor = b[i]
        result += bit_xor
    return result

if __name__ == "__main__":
    test_cases = [("010", "110"), ("10110110", "11110111")]
    for a, b in test_cases:
        print(f"{string_xor(a, b)}")
